select m.id, 'SkyLane-s287', 'create', 'S287 SkyLane write on 2026-09-24 after the MAP load refusal and Sam''s correction; rows, log and verify in one call (kb/receipts/cpl_memory_2026-09-24_s287_skylane.sql)', to_jsonb(m)
from public.cpl_memory m
where m.author = 'SkyLane-s287' and m.slug in ('map-student-credit-key-range-is-a-check-constraint-widened-to-250k', 'an-interrupted-tool-call-is-not-a-decline')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, m.status, count(l.id) filter (where l.action = 'create') as creates
